import { useMemo, useState } from 'react';
import { JxChip, JxProgressCircle, JxBadge, JxPagination, JxEmptyState, JxButton } from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over' | 'completed';

interface Project {
  id: string;
  name: string;
  quota: number;
  status: ProjectStatus;
}

const STATUS_META: Record<ProjectStatus, { label: string; tone: 'success' | 'warning' | 'danger' | 'info' }> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'На паузе', tone: 'warning' },
  over: { label: 'Превышен', tone: 'danger' },
  completed: { label: 'Завершён', tone: 'info' },
};

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Редизайн лендинга', quota: 72, status: 'active' },
  { id: 'p2', name: 'Миграция на новый биллинг', quota: 100, status: 'over' },
  { id: 'p3', name: 'Мобильное приложение', quota: 45, status: 'active' },
  { id: 'p4', name: 'Аналитика воронки', quota: 30, status: 'paused' },
  { id: 'p5', name: 'Интеграция с CRM', quota: 100, status: 'completed' },
  { id: 'p6', name: 'Обновление дизайн-системы', quota: 61, status: 'active' },
  { id: 'p7', name: 'Внутренний портал', quota: 88, status: 'over' },
  { id: 'p8', name: 'Поддержка партнёров', quota: 15, status: 'paused' },
  { id: 'p9', name: 'SEO-оптимизация', quota: 100, status: 'completed' },
  { id: 'p10', name: 'Тестовый стенд QA', quota: 54, status: 'active' },
  { id: 'p11', name: 'Каталог продуктов', quota: 22, status: 'paused' },
  { id: 'p12', name: 'Архив документов', quota: 100, status: 'completed' },
];

const PAGE_SIZE = 5;
const STATUS_OPTIONS = Object.keys(STATUS_META) as ProjectStatus[];

export default function ProjectQuotaPanel() {
  const [selectedStatuses, setSelectedStatuses] = useState<Set<ProjectStatus>>(new Set());
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setSelectedStatuses((prev) => {
      const next = new Set(prev);
      if (next.has(status)) {
        next.delete(status);
      } else {
        next.add(status);
      }
      return next;
    });
    setPage(1);
  };

  const resetFilters = () => {
    setSelectedStatuses(new Set());
    setPage(1);
  };

  const filteredProjects = useMemo(() => {
    if (selectedStatuses.size === 0) return PROJECTS;
    return PROJECTS.filter((project) => selectedStatuses.has(project.status));
  }, [selectedStatuses]);

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visibleProjects = filteredProjects.slice(
    (currentPage - 1) * PAGE_SIZE,
    currentPage * PAGE_SIZE
  );

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        padding: '20px',
        fontFamily: 'var(--jx-font-sans)',
        maxWidth: '640px',
      }}
    >
      <div>
        <h2
          style={{
            margin: 0,
            marginBottom: '4px',
            fontFamily: 'var(--jx-font-display)',
            color: 'var(--jx-text)',
            fontSize: '20px',
          }}
        >
          Расход по проектам
        </h2>
        <p style={{ margin: 0, color: 'var(--jx-text-2)', fontSize: '14px' }}>
          Заполненность квоты и статус по каждому проекту
        </p>
      </div>

      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {STATUS_OPTIONS.map((status) => {
          const isActive = selectedStatuses.has(status);
          return (
            <JxChip
              key={status}
              active={isActive}
              removable={isActive}
              onClick={() => toggleStatus(status)}
              onRemove={() => toggleStatus(status)}
            >
              {STATUS_META[status].label}
            </JxChip>
          );
        })}
      </div>

      {visibleProjects.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="По выбранным статусам нет ни одного проекта. Сбросьте фильтры, чтобы увидеть весь список."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {visibleProjects.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '16px',
                  padding: '12px 8px',
                  borderBottom: '1px solid var(--jx-rule)',
                }}
              >
                <span
                  style={{
                    flex: 1,
                    color: 'var(--jx-text)',
                    fontSize: '15px',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap',
                  }}
                >
                  {project.name}
                </span>
                <JxProgressCircle value={project.quota} showValue />
                <JxBadge tone={STATUS_META[project.status].tone}>
                  {STATUS_META[project.status].label}
                </JxBadge>
              </div>
            ))}
          </div>

          {pageCount > 1 && (
            <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
          )}
        </>
      )}
    </section>
  );
}

